#### Example 1: AWS MSK Cluster Configuration (Terraform)

```hcl
# Terraform configuration for Apache Kafka on AWS MSK
# Healthcare-compliant configuration with encryption, multi-AZ, CloudWatch monitoring

resource "aws_msk_cluster" "healthcare_events" {
  cluster_name           = "healthcare-event-broker-prod"
  kafka_version          = "3.5.1"
  number_of_broker_nodes = 6  # 2 nodes per AZ (us-east-1a, us-east-1b, us-east-1c)

  broker_node_group_info {
    instance_type   = "kafka.m5.large"  # 2 vCPU, 8 GB RAM, up to 10 Gbps network
    client_subnets  = [
      aws_subnet.private_us_east_1a.id,
      aws_subnet.private_us_east_1b.id,
      aws_subnet.private_us_east_1c.id
    ]
    security_groups = [aws_security_group.msk_broker.id]

    storage_info {
      ebs_storage_info {
        volume_size            = 1000  # 1 TB per broker (6 TB total cluster)
        provisioned_throughput {
          enabled           = true
          volume_throughput = 250  # MB/sec per broker
        }
      }
    }
  }

  # HIPAA-compliant encryption configuration
  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_encryption.arn
    encryption_in_transit {
      client_broker = "TLS"         # TLS encryption for client-broker communication
      in_cluster    = true          # TLS encryption between brokers
    }
  }

  # Enhanced monitoring with CloudWatch (required for SLA tracking)
  enhanced_monitoring = "PER_TOPIC_PER_BROKER"  # Detailed metrics per topic and broker

  # CloudWatch log delivery for audit trails
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "msk-broker-logs/"
      }
    }
  }

  # Client authentication using IAM (integrates with AWS IAM policies)
  client_authentication {
    sasl {
      iam = true  # AWS IAM authentication for producers/consumers
    }
  }

  tags = {
    Name        = "healthcare-event-broker-prod"
    Environment = "production"
    Domain      = "platform"
    Compliance  = "HIPAA"
    CostCenter  = "platform-engineering"
  }
}

# KMS key for encryption at rest
resource "aws_kms_key" "msk_encryption" {
  description             = "KMS key for MSK cluster encryption (HIPAA)"
  deletion_window_in_days = 30
  enable_key_rotation     = true  # Annual key rotation for compliance

  tags = {
    Name       = "msk-encryption-key"
    Compliance = "HIPAA"
  }
}

# CloudWatch alarms for SLA monitoring
resource "aws_cloudwatch_metric_alarm" "msk_cpu_high" {
  alarm_name          = "msk-cpu-utilization-high"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CpuUser"
  namespace           = "AWS/Kafka"
  period              = 300  # 5 minutes
  statistic           = "Average"
  threshold           = 80   # Alert if CPU > 80% for 10 minutes
  alarm_description   = "MSK broker CPU utilization high - consider scaling"
  alarm_actions       = [aws_sns_topic.platform_alerts.arn]

  dimensions = {
    "Cluster Name" = aws_msk_cluster.healthcare_events.cluster_name
  }
}

resource "aws_cloudwatch_metric_alarm" "msk_consumer_lag_high" {
  alarm_name          = "msk-consumer-lag-high"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "EstimatedMaxTimeLag"
  namespace           = "AWS/Kafka"
  period              = 300
  statistic           = "Maximum"
  threshold           = 300000  # 5 minutes lag in milliseconds
  alarm_description   = "MSK consumer lag exceeds 5 minutes - investigate slow consumers"
  alarm_actions       = [aws_sns_topic.platform_alerts.arn]

  dimensions = {
    "Cluster Name" = aws_msk_cluster.healthcare_events.cluster_name
  }
}
```

