#### Example 3: Java Producer with Schema Registry Integration

```java
// Java Spring Boot producer publishing claims events with Avro schema validation
// Integrates with AWS Glue Schema Registry for schema governance

import com.amazonaws.services.schemaregistry.serializers.GlueSchemaRegistryKafkaSerializer;
import com.amazonaws.services.schemaregistry.utils.AWSSchemaRegistryConstants;
import com.amazonaws.services.schemaregistry.utils.AvroRecordType;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;
import software.amazon.awssdk.services.glue.model.DataFormat;

import java.util.Properties;
import java.util.UUID;

public class ClaimsEventProducer {

    private final KafkaProducer<String, ClaimSubmitted> producer;
    private static final String TOPIC = "claims.submitted.v1";

    public ClaimsEventProducer(String bootstrapServers, String region) {
        Properties props = new Properties();

        // Basic Kafka producer configuration
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, GlueSchemaRegistryKafkaSerializer.class.getName());

        // Idempotent producer for exactly-once semantics
        props.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");
        props.put(ProducerConfig.ACKS_CONFIG, "all");  // Wait for all replicas to acknowledge
        props.put(ProducerConfig.RETRIES_CONFIG, Integer.MAX_VALUE);
        props.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, "5");

        // Compression for network efficiency
        props.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, "snappy");

        // Batching for throughput optimization
        props.put(ProducerConfig.BATCH_SIZE_CONFIG, "32768");  // 32 KB batches
        props.put(ProducerConfig.LINGER_MS_CONFIG, "10");      // Wait 10ms for batch to fill

        // AWS Glue Schema Registry configuration
        props.put(AWSSchemaRegistryConstants.AWS_REGION, region);
        props.put(AWSSchemaRegistryConstants.SCHEMA_AUTO_REGISTRATION_SETTING, "true");  // Auto-register new schemas
        props.put(AWSSchemaRegistryConstants.REGISTRY_NAME, "healthcare-events");
        props.put(AWSSchemaRegistryConstants.DATA_FORMAT, DataFormat.AVRO.name());
        props.put(AWSSchemaRegistryConstants.AVRO_RECORD_TYPE, AvroRecordType.SPECIFIC_RECORD.getName());
        props.put(AWSSchemaRegistryConstants.COMPATIBILITY_SETTING, "BACKWARD");  // Enforce backward compatibility

        this.producer = new KafkaProducer<>(props);
    }

    public void publishClaimSubmitted(ClaimSubmitted claim) {
        try {
            // Key by member ID for partition-based ordering (all events for same member in same partition)
            String key = claim.getMemberId();

            ProducerRecord<String, ClaimSubmitted> record = new ProducerRecord<>(TOPIC, key, claim);

            // Add headers for tracing and audit
            record.headers().add("event-id", UUID.randomUUID().toString().getBytes());
            record.headers().add("event-type", "ClaimSubmitted".getBytes());
            record.headers().add("event-version", "1.0".getBytes());
            record.headers().add("source-system", "claims-processing".getBytes());

            // Asynchronous send with callback for error handling
            producer.send(record, (metadata, exception) -> {
                if (exception != null) {
                    // Log error with claim ID for troubleshooting
                    log.error("Failed to publish claim {} to Kafka: {}", claim.getClaimId(), exception.getMessage(), exception);
                    // Implement retry strategy or dead-letter queue
                } else {
                    log.debug("Published claim {} to partition {} at offset {}",
                             claim.getClaimId(), metadata.partition(), metadata.offset());
                    // Emit metric for monitoring
                    metrics.counter("claims.published").increment();
                }
            });

        } catch (Exception e) {
            log.error("Unexpected error publishing claim: {}", e.getMessage(), e);
            throw new EventPublishException("Failed to publish claim event", e);
        }
    }

    public void close() {
        // Flush remaining messages and close producer gracefully
        producer.flush();
        producer.close();
    }
}

// Avro schema for ClaimSubmitted event (registered in Glue Schema Registry)
// Schema enforces backward compatibility (new fields must have defaults)
